#include <stdio.h>


int main(void)
{
    int leaves = 1;
    for (int depth = 0; depth < 3; depth++) {
        leaves *= 2;
    }
    printf("%d\n", leaves);
    return 0;
}

#include <stdio.h>


int main(void)
{
    int used = 1;
    used++;
    used--;
    printf("%d\n", used);
    return 0;
}

#include <stdio.h>


int main(void)
{
    int count = 0;
    for (unsigned mask = 0; mask < 16; mask++) {
        int used = 0;
        for (int bit = 0; bit < 4; bit++) {
            used += (mask >> bit) & 1u;
        }
        count += used == 2;
    }
    printf("%d\n", count);
    return 0;
}
